class Solution:
    def findJudge(self, n: int, trust: List[List[int]]) -> int:
        # convert this edges list -> adjacencies lists
        # Find the node with max num of adjacencies and compare with the num of nodes
        # if found a list the contains that node then false?
        incoming = collections.defaultdict(int)
        outgoing = collections.defaultdict(int)

        for src, dst in trust:
            outgoing[src] += 1
            incoming[dst] += 1

        for i in range(n):
            if outgoing[i + 1] == 0 and incoming[i + 1] == n - 1:
                return i + 1

        return - 1
